class Animal {
    String name;
    Animal(String name) { this.name = name; }
    String speak() { return "..."; }
}

class Dog extends Animal {
    Dog(String name) {
        super(name);            // must call, since Animal has no no-arg constructor
    }
    @Override
    String speak() {
        return name + " says Woof (base: " + super.speak() + ")";
    }
}

public class Main {
    public static void main(String[] args) {
        Dog d = new Dog("Rex");
        System.out.println(d.speak());   // Rex says Woof (base: ...)
    }
}
